const t2=M('III-2');if(t2){const r=D(t2),a=mx(r,3),b=mn(r,3),tt=TT(t2);o+=tbl('III-2')+p(`Pada Tahun ${yp}, ${W} berpenduduk ${f(tt[2],0)} jiwa dengan laju pertumbuhan rata-rata ${pc(tt[3])} per tahun dan rasio jenis kelamin ${f(tt[4],1)}. Laju tertinggi terdapat di Kecamatan ${a[1]} (${pc(a[3])}) dan terendah di Kecamatan ${b[1]} (${pc(b[3])}), sedangkan rasio jenis kelamin berkisar ${f(mn(r,4)[4],1)}–${f(mx(r,4)[4],1)}, menunjukkan komposisi laki-laki dan perempuan yang relatif berimbang. Wilayah dengan pertumbuhan penduduk tertinggi cenderung menjadi lokasi peningkatan kebutuhan lahan permukiman dan layanan dasar, sehingga perlu dicermati dalam pengendalian alih fungsi lahan.`);K.push(`Laju pertumbuhan penduduk tertinggi terdapat di Kecamatan ${a[1]} (${pc(a[3])} per tahun)`)}
const t3b=M('III-3');if(t3b){const r=D(t3b),a=mx(r,4),tt=TT(t3b),ag=r.filter(x=>/Berusaha sendiri/i.test(x[1]))[0];o+=tbl('III-3')+fig('kerja',`Status Pekerjaan Utama Penduduk ${W} Tahun ${yp}`,r.map(x=>x[1]),r.map(x=>x[4]),' jiwa')+p(`Status pekerjaan utama penduduk didominasi ${a[1]} sebanyak ${f(a[4],0)} jiwa (${pc(a[4]/tt[4]*100)} dari ${f(tt[4],0)} penduduk bekerja), diikuti ${srt(r,4)[1][1]} sebanyak ${f(srt(r,4)[1][4],0)} jiwa. Pekerja laki-laki berjumlah ${f(tt[2],0)} jiwa dan perempuan ${f(tt[3],0)} jiwa. Komposisi ini mencerminkan struktur ekonomi yang bertumpu pada kegiatan berupah dan usaha non-pertanian; kondisi tersebut dapat memperkuat tekanan terhadap tanah karena nilai ekonomi kegiatan perkotaan memberi insentif lebih besar bagi pemilik lahan untuk mengalihkan tanah produktif ke fungsi komersial.`)}
[['III-4','ADHB'],['III-5','ADHK']].forEach(([k,n])=>{const t=M(k);if(!t)return;const r=D(t),tt=TT(t),a=tt[2],z=tt.at(-1),g=(Math.pow(z/a,1/(t.head[0].length-3))-1)*100,tp=srt(r,t.head[0].length-1).slice(0,3),A=r.find(x=>x[0]=='A'),sA=A?A.at(-1)/z*100:0,gA=A?(Math.pow(A.at(-1)/A[2],1/(t.head[0].length-3))-1)*100:0;
o+=tbl(k)+p(`PDRB ${n} ${W} meningkat dari Rp ${f(a)} miliar pada ${ya} menjadi Rp ${f(z)} miliar pada ${yp} atau tumbuh rata-rata ${pc(g)} per tahun. Penyumbang terbesar adalah ${L(tp.map(x=>`${x[1]} (Rp ${f(x.at(-1))} miliar)`))}.${A?` Sektor pertanian, kehutanan, dan perikanan berkontribusi ${pc(sA)} dengan pertumbuhan ${pc(gA)} per tahun${gA<g?', lebih lambat daripada perekonomian secara keseluruhan':''}. ${k=='III-4'?'Pergeseran struktur ekonomi ke sektor perdagangan, industri, dan jasa meningkatkan permintaan ruang pada lokasi strategis; jika nilai ekonomi lahan untuk kegiatan perkotaan melampaui nilai produksi pertanian, lahan pertanian pada kawasan berkembang menghadapi tekanan alih fungsi.':'Pertumbuhan riil tersebut menegaskan peningkatan aktivitas ekonomi yang berimplikasi pada kebutuhan lahan untuk industri, perdagangan, jasa, dan infrastruktur pendukung.'}`:''}`);if(k=='III-4')K.push(`PDRB ADHB ${W} tumbuh rata-rata ${pc(g)} per tahun menjadi Rp ${f(z)} miliar pada ${yp}, ditopang ${tp[0][1]}`)});
o+=H(2,'Penggunaan Tanah')+p(`Penggunaan tanah adalah wujud tutupan permukaan bumi, baik bentukan alami maupun buatan manusia. Informasi ini mencerminkan pemanfaatan ruang aktual yang dinamis sehingga menjadi dasar mengidentifikasi perubahan. Dalam NPGT, kondisi tersebut disajikan melalui penggunaan tanah lama (G) Tahun ${y0} dan penggunaan tanah baru (Q) Tahun ${y1}.`);
const BU=/Kampung|Perumahan|Perkantoran|Industri|Jasa|Emplasemen|Olahraga|Gedung|Jalan/i;let sb={};
