const grp=(k,gi,vi)=>{const b=M(k);if(!b)return[];const g={};b.body.forEach(r=>{if(N(r[vi])&&!B(r[gi])&&!/^(Jumlah|Total)/.test(r[gi]))g[r[gi]]=(g[r[gi]]||0)+r[vi]});return Object.entries(g).sort((a,b)=>b[1]-a[1])};
