const r12=sh('IV-12');let ar={},tot12=0;if(r12){const d=blocks(r12)[0].slice(1);d.forEach(r=>{if(!N(r[4])||!r[3])return;const a=String(r[3]);const c=/^Tidak tersedia/i.test(a)?'Tidak tersedia':/Kawasan lindung/i.test(a)?'Penyesuaian di kawasan lindung':/dalam rangka optimalisasi/i.test(a)?'Optimalisasi penggunaan tanah':/sesuai tata ruang/i.test(a)?'Sesuai tata ruang':/dalam rangka penyesuaian/i.test(a)?'Penyesuaian penggunaan tanah':'Lainnya';ar[c]=(ar[c]||0)+r[4];tot12+=r[4]});const ae=Object.entries(ar).sort((a,b)=>b[1]-a[1]);
o+=tbl('IV-12')+p(`Arahan ketersediaan tanah dikelompokkan menjadi: <b>sesuai tata ruang</b> (tanah tersedia yang dapat dikembangkan sesuai pola ruang), <b>optimalisasi penggunaan tanah</b> (tanah yang telah digunakan sesuai fungsi dan dapat ditingkatkan efisiensinya), <b>penyesuaian penggunaan tanah</b> (penggunaan yang perlu disesuaikan dengan fungsi kawasan), <b>penyesuaian di kawasan lindung</b> (penggunaan pada fungsi lindung yang perlu dikendalikan), dan <b>tidak tersedia</b>. Secara agregat: ${L(ae.map(x=>`${x[0]} ${ha(x[1])} (${pc(x[1]/tot12*100)})`))}.`)+p(`Dominasi arahan ${ae[0][0].toLowerCase()} menunjukkan bahwa ${/Optimalisasi/.test(ae[0][0])?'kebutuhan ruang ke depan lebih tepat dipenuhi dengan menaikkan efisiensi tanah yang sudah digunakan daripada membuka lahan baru':'perhatian penatagunaan tanah perlu diarahkan pada kategori tersebut'}. Arahan penyesuaian, terutama pada kawasan lindung, merupakan sinyal tekanan ruang yang memerlukan penataan kembali sesuai pola penyesuaian pada Peraturan Pemerintah Nomor 16 Tahun 2004. Matriks arahan ketersediaan tanah (konversi penggunaan tanah terhadap arahan) mengikuti ketentuan Tata Cara Kerja NPGT Regional ${fl('lampirkan matriks arahan ketersediaan tanah dari juknis')}.`);K.push(`Arahan ketersediaan tanah: ${L(ae.slice(0,4).map(x=>`${x[0].toLowerCase()} ${ha(x[1])} (${pc(x[1]/tot12*100)})`))}; status tersedia tidak berarti dapat langsung dibangun karena tetap bergantung pada penggunaan eksisting, fungsi kawasan, dan penguasaan tanah`);RC.push(`Temuan ketersediaan tanah dapat dijadikan dasar menentukan ruang yang memerlukan penajaman, khususnya pada ${g11[0]?g11[0][0]:'fungsi kawasan terbesar'} serta ruang yang memerlukan penyesuaian penggunaan tanah dan kawasan lindung, dengan menelaah bersama penggunaan tanah eksisting, fungsi kawasan, dan penguasaan tanah`)}
