const t17=M('IV-17');if(t17){const r=D(t17),T=TT(t17),g=srt(r,4).filter(x=>x[4]>.5).slice(0,2),l=[...r].sort((a,b)=>a[4]-b[4]).filter(x=>x[4]<-.5).slice(0,3);o+=H(2,'Potensi Cadangan Karbon')+p(`Potensi cadangan karbon menggambarkan kemampuan wilayah menyimpan karbon berdasarkan penutup lahan. Informasi ini digunakan untuk melihat perubahan cadangan karbon akibat perubahan penggunaan tanah dan mengidentifikasi ruang yang perlu dipertimbangkan dalam pengendalian perubahan, terutama yang berpotensi menyimpan karbon tinggi (${rt('IV-17')}, ${rg('karbon')}, Lampiran 13 dan 14).`)+tbl('IV-17')+fig('karbon',`Perubahan Potensi Cadangan Karbon ${W} ${y0}-${y1} (Ton)`,r.map(x=>x[1]),r.map(x=>x[4]),'')+ph(`Peta Potensi Cadangan Karbon Tahun ${y0} ${W}`)+ph(`Peta Potensi Cadangan Karbon Tahun ${y1} ${W}`)+p(`Total potensi cadangan karbon ${W} ${T[4]>=0?'meningkat':'menurun'} dari ${f(T[2])} ton pada ${y0} menjadi ${f(T[3])} ton pada ${y1}, atau ${T[4]>=0?'surplus':'defisit'} ${f(Math.abs(T[4]))} ton (${pc(T[4]/T[2]*100)}). ${g.length?`Peningkatan terutama bersumber dari ${L(g.map(x=>`${x[1]} (+${f(x[4])} ton)`))}`:''}${l.length?`${g.length?', namun':'Penurunan terjadi pada'} ${g.length?'terjadi':''} ${g.length?'penurunan pada ':''}${L(l.map(x=>`${x[1]} (${f(x[4])} ton)`))}`:''}. Peningkatan karbon pada kelas permukiman atau lahan terbuka bukan indikator perbaikan lingkungan, karena nilainya berasal dari perubahan kelas penutup lahan, sementara penurunan pada sawah, pertanian lahan kering, dan vegetasi menandakan hilangnya ruang yang berfungsi ekologis. Karena itu, perubahan neto yang tampak surplus tidak boleh ditafsirkan sebagai membaiknya kondisi lingkungan.`);K.push(`Potensi cadangan karbon ${T[4]>=0?'meningkat':'menurun'} ${f(Math.abs(T[4]))} ton menjadi ${f(T[3])} ton, dengan penurunan pada ${l.length?L(l.map(x=>x[1].toLowerCase())):'beberapa kelas'}; surplus neto tidak serta-merta mencerminkan perbaikan lingkungan`);RC.push(`Sebaran perubahan cadangan karbon dapat menjadi dasar memperkuat perlindungan ruang berfungsi ekologis, terutama ${l.length?L(l.map(x=>x[1].toLowerCase())):'sawah dan vegetasi'}, melalui pemantauan perubahan penutup lahan oleh Kementerian ATR/BPN dan pemerintah daerah serta kebijakan kementerian/lembaga yang berwenang`)}
